import{J as e,n as t,ot as n,q as r}from"./chunks/framework.BKFk3dQW.js";var i=JSON.parse(`{"title":"One lifecycle event bus replaces the legacy emitter","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"One lifecycle event bus replaces the legacy emitter"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/adr/0017-one-lifecycle-event-bus"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/adr/0017-one-lifecycle-event-bus"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/adr/0017-one-lifecycle-event-bus.md"}},"headers":[],"relativePath":"adr/0017-one-lifecycle-event-bus.md","filePath":"adr/0017-one-lifecycle-event-bus.md","lastUpdated":1794501406000}`),a={name:`adr/0017-one-lifecycle-event-bus.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="one-lifecycle-event-bus-replaces-the-legacy-emitter" tabindex="-1">One lifecycle event bus replaces the legacy emitter <a class="header-anchor" href="#one-lifecycle-event-bus-replaces-the-legacy-emitter" aria-label="Permalink to “One lifecycle event bus replaces the legacy emitter”">​</a></h1><p>Status: accepted</p><p>The change log (<a href="/pr-preview/pr-3043/adr/0012-the-change-log-is-the-history.html">ADR 0012</a>) and the staged guards (<a href="/pr-preview/pr-3043/adr/0013-vetoable-actions-are-staged.html">ADR 0013</a>) replace the simulation events. The lifecycle events that remain, such as connect, disconnect, spawn, command and recipe registration, and the raknet events, move to the kernel&#39;s scoped event bus. The legacy <code>EventEmitter</code>, its separate plugin event bus and the awaited <code>tick</code> event are deleted. A scheduled callback in the style of the Script API&#39;s <code>system.run</code> runs at a fixed point of a tick and never when it was scheduled. The Script API host design picks the point. Bedrock&#39;s typings say such a callback &quot;will generally run the code at the end of the same tick where the event occurred&quot;, which the input step of the next tick would not match. Chat becomes a guarded action under ADR 0013.</p><p>The two buses order listeners differently. The legacy emitter calls every listener at once through <code>Promise.all</code>, and the kernel bus awaits them one at a time in subscription order. The kernel bus is typed, orders listeners by subscription, and detaches a module&#39;s listeners when that module stops, so it keeps a single ordering rule.</p></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};